    this.progression=progression;this.onGrowth=onGrowth;this.roundSerial=0;this.audio=audio;this.onToggleSound=onToggleSound;this.onRevive=onRevive;this.onRestart=onRestart;this.announce=announce;this.root=document.getElementById('ad-screen');this.canvas=document.getElementById('ad-canvas');this.skip=document.getElementById('ad-skip');this.renderer=new AdRenderer(this.canvas);this.session=null;this.order=new AdShuffleBag();this.raf=0;this.last=0;this.focused=true;this.pointer=null;this.oldFocus=null;
